package com.picviewer.app;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.app.*;import android.view.*;import android.widget.*;import java.util.*;import com.picviewer.core.*;
@RunWith(RobolectricTestRunner.class) @org.robolectric.annotation.Config(sdk=34,qualifiers="w600dp-h960dp-port-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class ViewingTest {
 public static class TestActivity extends MainActivity {@Override long frameBudget(){return 32*NextFrame.MIB;}}
 MainActivity a;
 @Before public void init(){a=Robolectric.buildActivity(TestActivity.class).setup().get();}
 @After public void end(){a.onDestroy();a.captureDates.close();}
 void settle()throws Exception{for(int i=0;i<10;i++){a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}}
 Calendar at(int hour,int minute){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,hour);c.set(Calendar.MINUTE,minute);return c;}
 @Test public void midnightWindowBoundaries(){assertTrue(ViewingOptions.inNight(1320,1320,420));assertTrue(ViewingOptions.inNight(0,1320,420));assertFalse(ViewingOptions.inNight(420,1320,420));assertFalse(ViewingOptions.inNight(800,1320,420));assertFalse(ViewingOptions.inNight(0,0,0));}
 @Test public void daytimeWindowBoundaries(){assertFalse(ViewingOptions.inNight(499,500,600));assertTrue(ViewingOptions.inNight(500,500,600));assertFalse(ViewingOptions.inNight(600,500,600));}
 @Test public void strictTimes(){assertEquals(1439,ViewingOptions.minute("23:59"));for(String s:new String[]{"24:00","9:30","22:60","xx:yy","-1:00"})try{ViewingOptions.minute(s);fail(s);}catch(IllegalArgumentException expected){}}
 @Test public void nightDimsPausesAndDayResumes(){a.startDemo();a.startPlayback(null);a.prefs.edit().putBoolean("night",true).putBoolean("nightPause",true).putInt("nightBrightness",12).apply();a.viewing.applyNight(at(23,0));assertEquals(.12f,a.getWindow().getAttributes().screenBrightness,.001);assertTrue(a.paused);assertTrue(a.viewing.nightPaused);assertEquals(0,a.getWindow().getAttributes().flags&128);a.viewing.applyNight(at(8,0));assertFalse(a.paused);assertFalse(a.viewing.nightPaused);assertEquals(-1f,a.getWindow().getAttributes().screenBrightness,.001);}
 @Test public void existingManualPauseIsNotResumedBySchedule(){a.startDemo();a.startPlayback(null);a.paused=true;a.prefs.edit().putBoolean("night",true).apply();a.viewing.applyNight(at(23,0));a.viewing.applyNight(at(8,0));assertTrue(a.paused);}
 @Test public void galleryRestoresSystemBrightness(){a.startDemo();a.startPlayback(null);a.prefs.edit().putBoolean("night",true).apply();a.viewing.applyNight(at(23,0));a.gallery();assertEquals(-1f,a.getWindow().getAttributes().screenBrightness,0);}
 @Test public void defaultsDoNotAddOverlayOrFade(){a.startDemo();a.startPlayback(null);assertNull(a.viewing.overlay);assertFalse(((FrameImageView)a.picture).fade);assertEquals(2,a.player.getChildCount());}
 @Test public void selectiveInfoIsSeparateFromControls()throws Exception{a.prefs.edit().putBoolean("infoClock",true).putBoolean("infoDate",true).putBoolean("infoFile",true).putInt("infoCorner",3).putInt("infoOpacity",60).apply();a.startDemo();a.startPlayback(null);settle();a.viewing.updateOverlay();assertNotNull(a.viewing.overlay);assertTrue(a.viewing.overlay.getText().toString().contains("촬영일 정보 없음"));assertTrue(a.viewing.overlay.getText().toString().contains(a.lookup(a.playlist.current()).name()));assertEquals(.6f,a.viewing.overlay.getAlpha(),.001);capture(a.getWindow().getDecorView(),"viewing-info",600,960);}
 @Test public void zoomPausesAndClampsAndResets()throws Exception{a.startDemo();a.startPlayback(null);settle();FrameImageView p=(FrameImageView)a.picture;p.setZoom(9);assertEquals(4,p.zoom,0);assertTrue(a.paused);p.panX=99999;p.panY=-99999;p.clamp();assertTrue(p.panX<=p.getWidth()*1.5);p.setZoom(1);assertEquals(0,p.panX,0);assertEquals(0,p.panY,0);p.setZoom(2);a.advance(false);settle();assertEquals(1,p.zoom,0);}
 @Test public void blurBackdropBoundedAndReleases()throws Exception{a.prefs.edit().putInt("displayMode",2).apply();a.startDemo();a.startPlayback("가족/03-portrait.jpg");settle();FrameImageView p=(FrameImageView)a.picture;assertNotNull(p.backdrop);assertEquals(24,p.backdrop.getWidth());a.toolbar.setVisibility(View.GONE);capture(a.getWindow().getDecorView(),"viewing-blur-portrait",600,960);android.graphics.Bitmap b=p.backdrop;a.gallery();assertTrue(b.isRecycled());}
 @Test public void fadeUsesOwnCopyAndReleases()throws Exception{a.prefs.edit().putBoolean("fade",true).apply();a.startDemo();a.startPlayback(null);settle();FrameImageView p=(FrameImageView)a.picture;android.graphics.Bitmap first=a.shown;a.advance(false);settle();assertNotNull(p.previous);assertNotSame(first,p.previous);assertFalse(first.isRecycled());android.graphics.Bitmap transition=p.previous;p.fadeStart-=400;capture(p,"viewing-transition-end",600,960);assertTrue(transition.isRecycled());assertNull(p.previous);}
 @Test public void lowMemorySkipsTransition()throws Exception{MainActivity low=Robolectric.buildActivity(MainActivity.class).setup().get();try{low.prefs.edit().putBoolean("fade",true).apply();low.startDemo();low.startPlayback(null);low.decode.submit(()->{}).get();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();FrameImageView p=(FrameImageView)low.picture;android.app.ActivityManager.MemoryInfo info=new android.app.ActivityManager.MemoryInfo();info.lowMemory=true;Shadows.shadowOf((android.app.ActivityManager)low.getSystemService(android.content.Context.ACTIVITY_SERVICE)).setMemoryInfo(info);p.setImageBitmap(android.graphics.Bitmap.createBitmap(10,10,android.graphics.Bitmap.Config.ARGB_8888));assertNull(p.previous);}finally{low.onDestroy();}}
 @Test public void dateParsingStrictAndNoTimezoneGuess(){assertEquals("2024-02-29 12:34:56",CaptureDates.normalize("2024:02:29 12:34:56"));for(String s:new String[]{"2023:02:29 00:00:00","0000:00:00 00:00:00","bad",""})assertEquals("",CaptureDates.normalize(s));}
 @Test public void metadataReadsExifAndVersionKeyAndNeverWritesOriginal()throws Exception{java.io.File f=new java.io.File(a.getCacheDir(),"date.jpg");android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(20,20,android.graphics.Bitmap.Config.ARGB_8888);try(java.io.FileOutputStream out=new java.io.FileOutputStream(f)){b.compress(android.graphics.Bitmap.CompressFormat.JPEG,90,out);}b.recycle();androidx.exifinterface.media.ExifInterface ex=new androidx.exifinterface.media.ExifInterface(f);ex.setAttribute(androidx.exifinterface.media.ExifInterface.TAG_DATETIME_ORIGINAL,"2020:05:01 12:13:14");ex.saveAttributes();byte[] before=java.nio.file.Files.readAllBytes(f.toPath());Photo p=new Photo("test.jpg",f.length(),1);a.captureDates.read(p,"synthetic-source",f);assertEquals("2020-05-01 12:13:14",a.captureDates.date(p,"synthetic-source"));assertEquals("",a.captureDates.date(new Photo("test.jpg",f.length(),2),"synthetic-source"));assertEquals("",a.captureDates.date(p,"other"));assertArrayEquals(before,java.nio.file.Files.readAllBytes(f.toPath()));CaptureDates reopened=new CaptureDates(a);try{assertEquals("2020-05-01 12:13:14",reopened.date(p,"synthetic-source"));}finally{reopened.close();}}
 @Test public void dateSortMissingLastWithFilenameTie(){Photo older=new Photo("z.jpg",1,1),newer=new Photo("a.jpg",1,1),missing=new Photo("0.jpg",1,1);a.captureDates.dates.put(older.key(a.config.source()),"2020-01-01 00:00:00");a.captureDates.dates.put(newer.key(a.config.source()),"2022-01-01 00:00:00");Playlist p=new Playlist(false,1);p.comparator=a.captureDates.comparator(a.config.source());p.reset(Arrays.asList(missing,newer,older),null);assertEquals(Arrays.asList("z.jpg","a.jpg","0.jpg"),p.order);assertEquals("a.jpg",p.next(Arrays.asList(missing,newer,older)));}
 @Test public void viewingSettingsDialogScrollableOutsideSafe()throws Exception{a.viewing.settings();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();MotionEvent e=MotionEvent.obtain(0,0,MotionEvent.ACTION_OUTSIDE,-100,-100,0);d.onTouchEvent(e);e.recycle();assertTrue(d.isShowing());capture(d.getWindow().getDecorView(),"viewing-settings-top",600,880);d.dismiss();}
 @Test public void orientationPreferenceRestored(){a.prefs.edit().putInt("orientation",1).apply();a.viewing.applyOrientation();assertEquals(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,a.getRequestedOrientation());}
 @Test public void metadataIndexStopsWhenPlaybackStarts(){a.startDemo();a.viewing.indexing=true;a.viewing.cancelIndex=false;a.startPlayback(null);assertTrue(a.viewing.cancelIndex);}
 @Test public void settingsApplyPersistsAndDoesNotAdvanceBehindDialog()throws Exception{a.startDemo();a.startPlayback(null);settle();String before=a.playlist.current();a.viewing.settings();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(a.intervalOpen);AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();java.util.List<Spinner> sp=new ArrayList<>();collectSpinners(d.getWindow().getDecorView(),sp);sp.get(0).setSelection(2);sp.get(1).setSelection(2);sp.get(2).setSelection(1);d.getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(d.isShowing());assertFalse(a.intervalOpen);assertEquals(2,a.prefs.getInt("displayMode",0));assertEquals(1,a.prefs.getInt("sortMode",0));assertEquals(before,a.playlist.current());assertTrue(((FrameImageView)a.picture).blurMode);}
 void collectSpinners(View v,java.util.List<Spinner> result){if(v instanceof Spinner){result.add((Spinner)v);return;}if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)collectSpinners(((android.view.ViewGroup)v).getChildAt(i),result);}
 @Test public void cancelledSettingsDoNotWrite(){a.viewing.settings();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();java.util.List<Spinner> sp=new ArrayList<>();collectSpinners(d.getWindow().getDecorView(),sp);sp.get(0).setSelection(2);d.getButton(-2).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(0,a.prefs.getInt("displayMode",0));}
 @Test public void invalidNightWindowStaysOpen(){a.prefs.edit().putInt("nightStart",1320).putInt("nightEnd",1320).apply();a.viewing.settings();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();d.getButton(-1).performClick();assertTrue(d.isShowing());d.dismiss();}
 @Test public void dateComparatorSurvivesCycleAndPeek(){a.startDemo();a.prefs.edit().putInt("sortMode",1).apply();for(int i=0;i<a.all.size();i++)a.captureDates.dates.put(a.all.get(i).key(a.config.source()),"202"+(4-i)+"-01-01 00:00:00");a.startPlayback(null);assertNotNull(a.playlist.comparator);for(int i=0;i<10;i++){String expected=a.nextPath();a.playlist.next(a.selected());assertEquals(expected,a.playlist.current());}}
 @Test public void portraitRenderingAndZoomCapture()throws Exception{a.prefs.edit().putInt("displayMode",2).apply();a.startDemo();a.startPlayback("가족/03-portrait.jpg");settle();assertEquals("가족/03-portrait.jpg",a.playlist.current());a.toolbar.setVisibility(View.GONE);capture(a.getWindow().getDecorView(),"viewing-portrait",600,960);capture(a.getWindow().getDecorView(),"viewing-portrait-wide",960,600);FrameImageView p=(FrameImageView)a.picture;p.setZoom(2);p.panX=50;p.panY=25;a.toolbar.setVisibility(View.GONE);capture(a.getWindow().getDecorView(),"viewing-zoom",600,960);}
 @Test public void repeatedNavigationReleasesTransientImages()throws Exception{a.prefs.edit().putBoolean("fade",true).putInt("displayMode",2).apply();a.startDemo();a.startPlayback(null);settle();FrameImageView p=(FrameImageView)a.picture;for(int i=0;i<80;i++){a.advance(i%3==0);settle();assertFalse(a.shown.isRecycled());assertTrue(a.nextFrame.bytes<=48*NextFrame.MIB);p.setZoom(i%2==0?2:1);p.fadeStart-=400;if(p.previous!=null)p.discardPrevious();}a.gallery();assertNull(p.previous);assertNull(p.backdrop);}
 @Test public void nightPauseDisabledDoesNotStopPlay(){a.startDemo();a.startPlayback(null);a.prefs.edit().putBoolean("night",true).putBoolean("nightPause",false).apply();a.viewing.applyNight(at(23,0));assertFalse(a.paused);assertFalse(a.viewing.nightPaused);}
 @Test public void noOfflineAlbumOrNewStoragePermission(){assertEquals(256L*1024*1024,a.images.maxCache);assertFalse(a.prefs.getAll().containsKey("offlineAlbum"));}
 @Test public void swipeWhileZoomedDoesNotNavigate()throws Exception{a.startDemo();a.startPlayback(null);settle();String before=a.playlist.current();FrameImageView p=(FrameImageView)a.picture;p.setZoom(2);long t=android.os.SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,200,300,0),move=MotionEvent.obtain(t,t+60,MotionEvent.ACTION_MOVE,450,400,0),up=MotionEvent.obtain(t,t+120,MotionEvent.ACTION_UP,450,400,0);p.onTouchEvent(down);p.onTouchEvent(move);p.onTouchEvent(up);down.recycle();move.recycle();up.recycle();assertEquals(before,a.playlist.current());assertTrue(a.paused);}
 @Test public void pauseDropsTransitionOnlyNotCurrent()throws Exception{a.prefs.edit().putBoolean("fade",true).apply();a.startDemo();a.startPlayback(null);settle();a.advance(false);settle();FrameImageView p=(FrameImageView)a.picture;android.graphics.Bitmap current=a.shown;assertNotNull(p.previous);a.onPause();assertNull(p.previous);assertFalse(current.isRecycled());}
 @Test public void settingsBottomCapture()throws Exception{a.viewing.settings();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();capture(d.getWindow().getDecorView(),"viewing-settings-top",600,880);ScrollView sc=d.getWindow().getDecorView().findViewWithTag("viewing-options-scroll");assertNotNull(sc);sc.setDescendantFocusability(android.view.ViewGroup.FOCUS_BLOCK_DESCENDANTS);sc.clearFocus();sc.scrollTo(0,3000);assertTrue(sc.getScrollY()>0);capture(d.getWindow().getDecorView(),"viewing-settings-bottom",600,880);d.dismiss();}
 ScrollView findScroll(View v){if(v instanceof ScrollView)return (ScrollView)v;if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){ScrollView s=findScroll(((android.view.ViewGroup)v).getChildAt(i));if(s!=null)return s;}return null;}
 void capture(View v,String name,int w,int h)throws Exception{v.measure(View.MeasureSpec.makeMeasureSpec(w,1073741824),View.MeasureSpec.makeMeasureSpec(h,1073741824));v.layout(0,0,w,h);v.jumpDrawablesToCurrentState();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.OutputStream out=new java.io.FileOutputStream(System.getProperty("picviewer.screenshots")+"/"+name+".png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
